import{_ as s,o as a,c as t,ae as i}from"./chunks/framework.1Lna8NcP.js";const u=JSON.parse('{"title":"Libertas Landing Redesign — Design Spec","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-04-14-libertas-landing-design.md","filePath":"superpowers/specs/2026-04-14-libertas-landing-design.md"}'),n={name:"superpowers/specs/2026-04-14-libertas-landing-design.md"};function o(l,e,r,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="libertas-landing-redesign-—-design-spec" tabindex="-1">Libertas Landing Redesign — Design Spec <a class="header-anchor" href="#libertas-landing-redesign-—-design-spec" aria-label="Permalink to &quot;Libertas Landing Redesign — Design Spec&quot;">​</a></h1><p><strong>Date:</strong> 2026-04-14 <strong>Status:</strong> Approved, ready for plan <strong>Scope:</strong> Full overhaul of <code>docs/</code> VitePress site into a high-conversion product landing. No ADRs in public nav. Theme preserved + elevated (no palette rewrite).</p><hr><h2 id="_1-goals" tabindex="-1">1. Goals <a class="header-anchor" href="#_1-goals" aria-label="Permalink to &quot;1. Goals&quot;">​</a></h2><ul><li>High-conversion, &quot;super salesy&quot; single-page landing at <code>/</code></li><li>Clear, scannable — current site is text-heavy and disorganized</li><li>Audience: self-directed people with many accounts who want consolidation, clarity, trajectory, and control (NOT wealth optimization, NOT cashflow budgeting)</li><li>Preserve existing blue/Manrope/Instrument Serif theme; elevate fidelity</li><li>Remove ADRs from public surface (files stay in repo, unlinked)</li><li>Works on GitHub Pages (static only) at base <code>/Libertas/</code></li></ul><h2 id="_2-non-goals" tabindex="-1">2. Non-Goals <a class="header-anchor" href="#_2-non-goals" aria-label="Permalink to &quot;2. Non-Goals&quot;">​</a></h2><ul><li>No palette/typography rewrite</li><li>No social proof section v1 (no stars/quotes/press available yet — slot reserved)</li><li>No blog / changelog</li><li>No i18n</li><li>No in-browser demo of the app (screenshots only; app runs only on user&#39;s machine)</li><li>No SSR / dynamic content</li></ul><h2 id="_3-information-architecture" tabindex="-1">3. Information Architecture <a class="header-anchor" href="#_3-information-architecture" aria-label="Permalink to &quot;3. Information Architecture&quot;">​</a></h2><p>Single-page scrollytelling landing + thin feature pages.</p><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/</code></td><td>Conversion-focused scrollytelling landing</td></tr><tr><td><code>/features/</code></td><td>Index of 6 feature detail pages</td></tr><tr><td><code>/features/&lt;slug&gt;</code></td><td>One per feature: dashboard, accounts, import, real-estate, projections, insights</td></tr><tr><td><code>/privacy/</code></td><td>&quot;Why local-first&quot; deep dive</td></tr><tr><td><code>/download/</code></td><td>Install + quickstart</td></tr></tbody></table><p><strong>Nav:</strong> <code>Features · Why Private · Download</code> + GitHub icon.</p><p><strong>ADRs:</strong> <code>docs/adr/*.md</code> remain in repo. Removed from VitePress nav + sidebar config. Not linked from any public page.</p><h2 id="_4-messaging" tabindex="-1">4. Messaging <a class="header-anchor" href="#_4-messaging" aria-label="Permalink to &quot;4. Messaging&quot;">​</a></h2><p><strong>Primary hook:</strong> Consolidation — &quot;All your accounts. One private view.&quot; / &quot;Stop juggling 12 logins.&quot; <strong>Secondary hook:</strong> Trajectory/control — surfaced in walkthrough copy, feature page taglines, and section subheads.</p><p>No social proof v1. Leave visual slot between Feature Grid and Privacy section for later addition.</p><h2 id="_5-landing-page-sections-in-order" tabindex="-1">5. Landing Page Sections (in order) <a class="header-anchor" href="#_5-landing-page-sections-in-order" aria-label="Permalink to &quot;5. Landing Page Sections (in order)&quot;">​</a></h2><ol><li><strong>Hero</strong> — headline (consolidation), sub (trajectory/control), primary CTA &quot;Download&quot;, secondary &quot;See features&quot;. Dashboard screenshot right. Trust strip: &quot;100% local · No accounts · Open source · MIT&quot;.</li><li><strong>Problem</strong> — 3-line punch (&quot;12 logins. 5 spreadsheets. Zero clarity.&quot;)</li><li><strong>Sticky Product Walkthrough</strong> — 6 scroll steps, one per feature. Sticky screenshot crossfades on step change. Left copy: active bright, inactive dimmed 40%. Left-rail progress dots.</li><li><strong>Feature Grid</strong> — 6 cards linking to feature pages.</li><li><strong>[Proof slot — empty v1]</strong></li><li><strong>Privacy strip</strong> — 3 bullets + link to <code>/privacy/</code>.</li><li><strong>FAQ</strong> — 5–6 Q&amp;A (free? windows support? data location? price data? backup? import format?).</li><li><strong>Final CTA</strong> — download block + install one-liner + GitHub link.</li><li><strong>Footer</strong> — license, GitHub, docs.</li></ol><h2 id="_6-feature-detail-page-template" tabindex="-1">6. Feature Detail Page Template <a class="header-anchor" href="#_6-feature-detail-page-template" aria-label="Permalink to &quot;6. Feature Detail Page Template&quot;">​</a></h2><p>All 6 pages share layout, driven by frontmatter.</p><p>Sections:</p><ul><li>Hero strip — tagline + hero screenshot + Download CTA</li><li>What it does — 2 short paragraphs</li><li>How it works — 3 steps (icon + label + 1 line)</li><li>Private by design — 1 paragraph feature-specific</li><li>Screenshot gallery — 2–3 shots</li><li>Reused <code>CTABlock</code></li><li><code>← All features</code> back link</li></ul><h2 id="_7-architecture" tabindex="-1">7. Architecture <a class="header-anchor" href="#_7-architecture" aria-label="Permalink to &quot;7. Architecture&quot;">​</a></h2><p><strong>Stack:</strong> VitePress 1.6.3 (unchanged). Custom theme extension. All output static → GitHub Pages.</p><p><strong>File additions:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/.vitepress/theme/</span></span>
<span class="line"><span>  components/</span></span>
<span class="line"><span>    Hero.vue</span></span>
<span class="line"><span>    ProductWalkthrough.vue</span></span>
<span class="line"><span>    FeatureGrid.vue</span></span>
<span class="line"><span>    PrivacyStrip.vue</span></span>
<span class="line"><span>    FAQ.vue</span></span>
<span class="line"><span>    CTABlock.vue</span></span>
<span class="line"><span>  layouts/</span></span>
<span class="line"><span>    feature.vue</span></span>
<span class="line"><span>  index.ts               # register components + layout</span></span>
<span class="line"><span>  custom.css             # extended (not replaced)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docs/features/</span></span>
<span class="line"><span>  index.md</span></span>
<span class="line"><span>  dashboard.md</span></span>
<span class="line"><span>  accounts.md</span></span>
<span class="line"><span>  import.md</span></span>
<span class="line"><span>  real-estate.md</span></span>
<span class="line"><span>  projections.md</span></span>
<span class="line"><span>  insights.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docs/privacy/index.md    # new expanded privacy page</span></span>
<span class="line"><span>docs/download/index.md   # new install page</span></span>
<span class="line"><span>docs/public/screenshots/ # PNGs captured from real app</span></span>
<span class="line"><span></span></span>
<span class="line"><span>backend/seed_demo.py     # new — builds libertas-demo.db</span></span></code></pre></div><p><strong>File removals from nav only (files stay):</strong></p><ul><li><code>docs/technical.md</code> — delete (was public) or move under <code>docs/internal/</code> unlinked</li><li>ADR sidebar entries — removed from <code>config.ts</code></li></ul><h2 id="_8-design-tokens" tabindex="-1">8. Design Tokens <a class="header-anchor" href="#_8-design-tokens" aria-label="Permalink to &quot;8. Design Tokens&quot;">​</a></h2><p><strong>Preserved:</strong> all existing <code>--lp-*</code> and <code>--vp-c-brand-*</code> tokens, Manrope/Instrument Serif, light+dark modes.</p><p><strong>Added:</strong></p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-hero-grad         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* subtle mesh, not flat */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-card-bg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-card-border</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-card-hover</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-scroll-step-active</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-scroll-step-dim</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-shadow-screenshot</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-radius-lg: 16px</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-space-1.</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">.8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 4/8/12/16/24/40/64/96 (px)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-ease: cubic-bezier(</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">.22</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">.61</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">.36</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,1)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-dur-fast: 180ms</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--lp-dur-med: 360ms</span></span></code></pre></div><p><strong>Type scale bumps:</strong></p><ul><li>Hero h1: <code>clamp(2.5rem, 5vw, 4.5rem)</code></li><li>Section h2: <code>clamp(1.75rem, 3vw, 2.75rem)</code></li><li>Display serif: hero + section headings only, never body</li></ul><h2 id="_9-components" tabindex="-1">9. Components <a class="header-anchor" href="#_9-components" aria-label="Permalink to &quot;9. Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Props</th><th>Used on</th></tr></thead><tbody><tr><td><code>Hero.vue</code></td><td>headline, sub, ctaPrimary, ctaSecondary, screenshot, trustItems[]</td><td><code>/</code></td></tr><tr><td><code>ProductWalkthrough.vue</code></td><td>steps[] (copy, screenshot)</td><td><code>/</code></td></tr><tr><td><code>FeatureGrid.vue</code></td><td>features[] (icon, title, oneLine, href)</td><td><code>/</code>, <code>/features/</code></td></tr><tr><td><code>PrivacyStrip.vue</code></td><td>bullets[]</td><td><code>/</code></td></tr><tr><td><code>FAQ.vue</code></td><td>items[] (q, a)</td><td><code>/</code></td></tr><tr><td><code>CTABlock.vue</code></td><td>title, sub, installCmd</td><td><code>/</code>, all feature pages</td></tr><tr><td><code>feature.vue</code> (layout)</td><td>frontmatter-driven</td><td><code>/features/&lt;slug&gt;</code></td></tr></tbody></table><p>All registered in <code>theme/index.ts</code> for markdown usage.</p><p><code>ProductWalkthrough.vue</code> scroll logic: IntersectionObserver on step elements → sets active index → sticky image <code>&lt;img&gt;</code> sources swap with CSS opacity crossfade. No scroll listener. No layout thrash.</p><h2 id="_10-motion" tabindex="-1">10. Motion <a class="header-anchor" href="#_10-motion" aria-label="Permalink to &quot;10. Motion&quot;">​</a></h2><p><strong>Budget (all transforms + opacity only):</strong></p><ul><li>Hero: fade-up on load, screenshot float 400ms (one-shot)</li><li>Walkthrough: sticky crossfade 360ms between steps; copy active/dim transition 240ms; progress dots fill</li><li>Feature cards: hover lift 2px + border glow 180ms</li><li>FAQ: accordion expand 240ms ease-out</li><li>CTA: gradient shift on hover</li></ul><p><strong>Forbidden:</strong> parallax, autoplay video, scroll-jacking, number counters, particles, typewriter.</p><p><strong>Reduced motion:</strong> <code>prefers-reduced-motion: reduce</code> → all durations → 0ms. Sticky scroll still works, images snap-swap.</p><h2 id="_11-screenshot-pipeline" tabindex="-1">11. Screenshot Pipeline <a class="header-anchor" href="#_11-screenshot-pipeline" aria-label="Permalink to &quot;11. Screenshot Pipeline&quot;">​</a></h2><p><strong>Seed script</strong> — <code>backend/seed_demo.py</code>:</p><ul><li>Builds <code>libertas-demo.db</code> with realistic fake data</li><li>8 accounts: 2 Fidelity, 2 Schwab, 1 Coinbase, 2 Chase, 1 Vanguard</li><li>~40 holdings across equity/crypto/cash</li><li>6 months price history (synthetic but plausible curves)</li><li>2 real estate entries with overrides</li><li>Separate DB file — never touches <code>/data/libertas.db</code></li></ul><p><strong>Launch flag:</strong> <code>./start.sh --demo</code> → backend uses <code>libertas-demo.db</code>.</p><p><strong>Capture checklist</strong> (manual, executed during plan, not here):</p><ul><li>1440×900 viewport, light + dark mode each</li><li>6 hero shots (one per page) + 2–3 supporting each</li><li>Save: <code>docs/public/screenshots/&lt;slug&gt;.png</code>, <code>&lt;slug&gt;-dark.png</code></li><li>PNG, optimized via <code>oxipng</code> or equivalent</li></ul><h2 id="_12-performance-targets" tabindex="-1">12. Performance Targets <a class="header-anchor" href="#_12-performance-targets" aria-label="Permalink to &quot;12. Performance Targets&quot;">​</a></h2><ul><li>Lighthouse Performance ≥ 95 (static site, should be easy)</li><li>LCP &lt; 1.5s on 4G</li><li>No CLS from screenshot swaps (reserve aspect ratio containers)</li><li>All screenshots lazy except hero</li><li>Total JS on landing &lt; 80KB gzipped (VitePress baseline + one Vue component)</li></ul><h2 id="_13-accessibility" tabindex="-1">13. Accessibility <a class="header-anchor" href="#_13-accessibility" aria-label="Permalink to &quot;13. Accessibility&quot;">​</a></h2><ul><li>All interactive components keyboard-reachable (FAQ accordion, feature cards, CTAs)</li><li>Screenshots have descriptive alt text (not &quot;screenshot&quot;)</li><li>Sticky walkthrough: step copy remains semantic (headings + paragraphs), not visual-only</li><li>Color contrast ≥ AA in both modes</li><li>Respect <code>prefers-reduced-motion</code></li></ul><h2 id="_14-out-of-scope-deferred" tabindex="-1">14. Out of scope / deferred <a class="header-anchor" href="#_14-out-of-scope-deferred" aria-label="Permalink to &quot;14. Out of scope / deferred&quot;">​</a></h2><ul><li>Social proof section (gated on having real proof)</li><li>Changelog / release notes on public site</li><li>Email capture / mailing list</li><li>Dark-mode screenshot pairs — included in v1 capture pass, but if time-constrained, light-only is acceptable</li><li>A/B testing infra</li><li>Analytics — deferred decision (likely privacy-friendly or none)</li></ul><h2 id="_15-open-questions" tabindex="-1">15. Open questions <a class="header-anchor" href="#_15-open-questions" aria-label="Permalink to &quot;15. Open questions&quot;">​</a></h2><p>None blocking. All resolved during brainstorm.</p><hr><h2 id="appendix-a-—-content-to-write-during-implementation" tabindex="-1">Appendix A — Content to write during implementation <a class="header-anchor" href="#appendix-a-—-content-to-write-during-implementation" aria-label="Permalink to &quot;Appendix A — Content to write during implementation&quot;">​</a></h2><ul><li>6 feature taglines (one line each)</li><li>18 feature copy paragraphs (3 per feature page: what / how / private-angle)</li><li>6 walkthrough step copy blocks (~40 words each)</li><li>5–6 FAQ entries</li><li>Privacy page expanded content</li><li>Download page content</li></ul>`,59)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
